doc.codeblock:
CREATE TABLE items ( id TEXT PRIMARY KEY, source TEXT NOT NULL CHECK (source IN ('twitter','browser','github')), title TEXT NOT NULL, url TEXT NOT NULL, created_at TEXT, saved_at TEXT NOT NULL, saved_source TEXT CHECK (saved_source IN ('tweet_created','browser_added','first_seen')), imported_at TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'inbox' CHECK (status IN ('inbox','later','done','reference')), read INTEGER NOT NULL DEFAULT 0, is_todo INTEGER NOT NULL DEFAULT 0, todo_done INTEGER NOT NULL DEFAULT 0, metadata TEXT NOT NULL DEFAULT '{}', ai_tags TEXT NOT NULL DEFAULT '[]', ai_summary TEXT, summary TEXT, ai_state TEXT NOT NULL DEFAULT 'none' CHECK (ai_state IN ('none','suggested','accepted')), last_surfaced_at TEXT, deleted_at TEXT );
CREATE TABLE tags ( id INTEGER PRIMARY KEY, name TEXT NOT NULL UNIQUE );
CREATE TABLE item_tags ( item_id TEXT NOT NULL REFERENCES items(id), tag_id INTEGER NOT NULL REFERENCES tags(id), PRIMARY KEY (item_id, tag_id) );
CREATE TABLE ai_jobs ( id TEXT PRIMARY KEY, kind TEXT NOT NULL, status TEXT NOT NULL, total INTEGER NOT NULL, done INTEGER NOT NULL DEFAULT 0, error TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL );
CREATE TABLE settings ( key TEXT PRIMARY KEY, value TEXT NOT NULL );
CREATE VIRTUAL TABLE items_fts USING fts5( id UNINDEXED, title, text, summary );
